<?php use App\Auth; ?>
<?php if(!$rows): ?><div class="card-body py-5 text-center"><h2 class="h5">No records found</h2><p class="text-secondary">Clear your filters or try another name or identifier.</p><a class="btn btn-outline-primary" href="<?= e(url($route)) ?>">Clear filters</a></div><?php else: ?>
<div class="table-responsive directory-table-scroll"><table class="table table-hover align-middle mb-0" data-directory-table><thead><tr><th scope="col">Photo</th><?php if(\App\VoterService::namesReady()): ?><th scope="col" aria-sort="<?= ($filters['sort']==='last_name'?'ascending':($filters['sort']==='last_name_desc'?'descending':'none')) ?>"><a href="<?= e(url($route,array_replace($filters,['sort'=>$filters['sort']==='last_name'?'last_name_desc':'last_name','p'=>1]))) ?>">Last name <i class="bi bi-arrow-down-up" aria-hidden="true"></i></a></th><?php else: ?><th scope="col">Last name</th><?php endif; ?><?php if(\App\VoterService::namesReady()): ?><th scope="col" aria-sort="<?= ($filters['sort']==='first_name'?'ascending':($filters['sort']==='first_name_desc'?'descending':'none')) ?>"><a href="<?= e(url($route,array_replace($filters,['sort'=>$filters['sort']==='first_name'?'first_name_desc':'first_name','p'=>1]))) ?>">First name <i class="bi bi-arrow-down-up" aria-hidden="true"></i></a></th><?php else: ?><th scope="col">First name</th><?php endif; ?><th scope="col">Gender</th><th scope="col">Voter ID</th><?php if($membersOnly): ?><?php if(\App\MemberProfileService::ready()): ?><th scope="col" data-column-optional>Profession</th><th scope="col" data-column-optional>Education</th><?php endif; ?><?php endif; ?><?php if($addressCatalog): ?><th scope="col" data-column-optional>Residence</th><?php endif; ?><?php if($membersOnly): ?><th scope="col">Region</th><?php endif; ?><th scope="col" data-column-optional>Constituency</th><th scope="col" data-column-optional>Electoral area (branch)</th><th scope="col" data-column-optional>Polling station</th><th scope="col"><?= $membersOnly?'Status':'Membership' ?></th><th scope="col" class="directory-actions-cell">Actions</th></tr></thead><tbody>
<?php foreach($rows as $person): $profile=url($person['membership_id']?'member':'voter',['id'=>$person['membership_id']?:$person['id']]); ?>
<tr><td><a href="<?= e($profile) ?>" aria-label="View <?= e($person['full_name']) ?>"><?php if($person['has_photo']): ?><img class="directory-photo" src="<?= e(url('voter_photo',['id'=>$person['id']])) ?>" alt="Photo of <?= e($person['full_name']) ?>" width="44" height="52" loading="lazy" decoding="async"><?php else: ?><span class="directory-photo-placeholder" title="No photo added" aria-label="No photo added"><?= e(mb_strtoupper(mb_substr($person['full_name'],0,1))) ?></span><?php endif; ?></a></td>
<td><?php if(!empty($person['last_name'])): ?><a class="fw-semibold" href="<?= e($profile) ?>"><?= e($person['last_name']) ?></a><?php else: ?><span class="text-secondary">Not recorded</span><small class="table-detail">Saved full name: <a href="<?= e($profile) ?>"><?= e($person['full_name']) ?></a></small><?php endif; ?><?php if(!$membersOnly): ?><small class="table-detail"><?= e($person['region']??'Not assigned') ?></small><?php endif; ?></td><td><?php if(!empty($person['first_name'])): ?><a href="<?= e($profile) ?>"><?= e($person['first_name']) ?></a><?php else: ?><span class="text-secondary">Not recorded</span><?php endif; ?></td><td><?= e(match($person['gender']??'unknown'){'female'=>'Female','male'=>'Male','other'=>'Other',default=>'Not specified'}) ?></td><td><span class="location-id"><?= e($person['voter_id']) ?></span></td>
<?php if($membersOnly): ?><?php if(\App\MemberProfileService::ready()): ?><td><?= e($person['profession']??'Not recorded') ?><?php if(!empty($person['job_title'])): ?><small class="table-detail"><?= e($person['job_title']) ?></small><?php endif; ?></td><td><?= e(\App\MemberProfileService::EDUCATION[$person['education_level']??'']??'Not recorded') ?></td><?php endif; ?><?php endif; ?>
<?php if($addressCatalog): ?><td><?= e($person['town']??'Town not recorded') ?><small class="table-detail"><?= e(implode(' / ',array_filter([$person['residential_district']??null,$person['residential_region']??null]))) ?></small></td><?php endif; ?><?php if($membersOnly): ?><td><?= e($person['region']?:'Not assigned') ?><?php $memberRoleLevel='region';require \App\View::path('members/partials/directory_executive_roles'); ?></td><?php endif; ?><td><?= e($person['constituency']?:'Not assigned') ?><?php if($membersOnly): ?><small class="table-detail"><?php if(trim((string)($person['official_membership_id']??''))===''): ?><span class="badge bg-warning text-dark">Sys No.: <?= e($person['member_number']) ?></span><span class="d-block mt-1"><?php if(Auth::canManage()): ?><a href="<?= e(url('member_edit',['id'=>$person['membership_id']]).'#member-edit') ?>">Add Party ID <i class="bi bi-arrow-up-right" aria-hidden="true"></i></a><?php else: ?>Party ID not recorded<?php endif; ?></span><?php else: ?>Party ID: <span class="location-id"><?= e(member_identifier($person)) ?></span><?php endif; ?></small><?php endif; ?><?php $memberRoleLevel='constituency';require \App\View::path('members/partials/directory_executive_roles'); ?></td><td><?= e($person['electoral_area']?:'Branch not assigned') ?><?php $memberRoleLevel='branch';require \App\View::path('members/partials/directory_executive_roles'); ?></td><td><?= e($person['polling_station']?:'Not assigned') ?><?php if(!empty($person['polling_station_code'])): ?><small class="table-detail">ID: <?= e($person['polling_station_code']) ?></small><?php endif; ?><?php $memberRoleLevel='polling_station';require \App\View::path('members/partials/directory_executive_roles'); ?></td>
<td><?php if(!empty($person['is_deceased'])): ?><span class="badge bg-secondary">Deceased</span><br><?php endif; ?><?php if($membersOnly): ?><?= badge($person['membership_status']) ?><?php $memberRoleLevel='national';require \App\View::path('members/partials/directory_executive_roles'); ?><?php elseif($person['membership_id']): ?><a href="<?= e(url('member',['id'=>$person['membership_id']])) ?>"><?= e(member_identifier($person)) ?></a><small class="table-detail"><?= e(member_identifier_label($person)) ?><?php if(trim((string)($person['official_membership_id']??''))!==''): ?> · Sys No.: <?= e($person['member_number']) ?><?php endif; ?></small><?php else: ?>Not a member<?php endif; ?></td><td class="directory-actions-cell"><div class="d-flex flex-nowrap gap-2"><a class="btn btn-sm btn-light" href="<?= e($profile) ?>"><?= $person['membership_id']?'View member':(Auth::canManage()?'Open voter':'View voter') ?></a><?php if($person['membership_id']&&Auth::canManage()): ?><a class="btn btn-sm btn-outline-primary" href="<?= e(url('member_edit',['id'=>$person['membership_id']])) ?>" aria-label="Edit member <?= e($person['full_name']) ?>"><i class="bi bi-pencil" aria-hidden="true"></i><span class="visually-hidden">Edit member</span></a><?php endif; ?><?php if(!$person['membership_id']&&Auth::canManage()): ?><a class="btn btn-sm btn-outline-primary" href="<?= e(url('member_enroll',['id'=>$person['id']])) ?>">Mark as member</a><?php endif; ?></div></td></tr>
<?php endforeach; ?></tbody></table></div><?php endif; ?>
